CREATE TABLE IF NOT EXISTS sehatmitra.field_visits (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, author_id text NOT NULL, patient_alias text NOT NULL, note text NOT NULL, referral text NOT NULL DEFAULT '', follow_up_on date, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sehatmitra.audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id text NOT NULL, actor_role text NOT NULL, action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sehatmitra.notifications (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id text NOT NULL, message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
